function loadDxDropdownBox(componentId, textBoxId, url, id, isDisabled) {
    if (typeof isDisabled === 'undefined' || isDisabled === null) {
        isDisabled = false;
    }

    url = baseUrl + url;

    $(() => {
        var columns = [
            { 'name': 'Id', 'type': 'object' },
            { 'name': 'Text', 'type': 'string', 'caption': 'Value' }
        ];

        var key = columns[0].name;
        var dataColumns = renderDropdownColumns(columns);

        const makeAsyncDataSource = function () {
            return new DevExpress.data.CustomStore({
                loadMode: 'raw',
                key: key,
                load() {
                    return $.getJSON(url);
                },
                byKey(keyValue) {
                    return $.getJSON(url).then(function (items) {
                        return (items || []).find(function (item) {
                            return String(item[key]) === String(keyValue);
                        }) || null;
                    });
                },
            });
        };

        $('#' + componentId).dxDropDownBox({
            valueExpr: key,
            deferRendering: false,
            placeholder: 'Select a value...',
            displayExpr(item) {
                return item && `${item.Text}`;
            },
            readOnly: isDisabled,
            showClearButton: true,
            dataSource: makeAsyncDataSource(),
            contentTemplate(e) {
                const value = e.component.option('value');
                const $dataGrid = $('<div>').dxDataGrid({
                    dataSource: e.component.getDataSource(),
                    showColumnLines: true,
                    showRowLines: true,
                    rowAlternationEnabled: true,
                    showBorders: true, filterRow: {
                        visible: true,
                    },
                    headerFilter: {
                        visible: true,
                    },
                    remoteOperations: true,
                    paging: {
                        pageSize: 10,
                    },
                    showBorders: true,
                    columnAutoWidth: true,
                    allowColumnResizing: true,
                    scrolling: {
                        mode: "standard"
                    },
                    loadPanel: {
                        enabled: true
                    },
                    pager: {
                        visible: true,
                        showPageSizeSelector: true,
                        allowedPageSizes: [10, 50, 100],
                        showNavigationButtons: true,
                        showInfo: true
                    },
                    onContentReady: function (x) {
                        var index = DevExpress.localization.formatNumber(x.component.pageIndex() + 1, ",##0.###");
                        var count = DevExpress.localization.formatNumber(x.component.pageCount(), ",##0.###");
                        var total = DevExpress.localization.formatNumber(x.component.totalCount(), ",##0.###");
                        x.component.option("pager.infoText", "Page " + index + " of " + count + " (" + total + " items)");
                    },
                    columns: dataColumns,
                    hoverStateEnabled: true,
                    paging: { enabled: true, pageSize: 10 },
                    filterRow: { visible: true },
                    scrolling: { mode: 'virtual', useNative: false, showScrollbar: 'onScroll' },
                    selection: { mode: 'single' },
                    selectedRowKeys: [value],
                    height: '100%',
                    onSelectionChanged(selectedItems) {
                        const keys = selectedItems.selectedRowKeys;
                        const hasSelection = keys.length;

                        e.component.option('value', hasSelection ? keys[0] : null);
                        var valueSelect = hasSelection ? keys[0] : null;

                        if (valueSelect === null && id !== null && id !== "") {
                            if (id !== '00000000-0000-0000-0000-000000000000' && id !== '0') {
                                valueSelect = id;
                                e.component.option('value', id);
                            }
                        }

                        $('#' + textBoxId).val(valueSelect);
                        if (hasSelection) {
                            e.component.close();
                        }
                    }
                });

                dataGrid = $dataGrid.dxDataGrid("instance");
                e.component.on("valueChanged", function (args) {
                    if (args.value === null || args.value === "") {
                        dataGrid.deselectAll();
                        dataGrid.clearSelection();
                    }
                    $('#' + textBoxId).val(args.value);
                });

                return $dataGrid;
            },
        });
    });
}

function loadDxDropdownBoxColumn(componentId, textBoxId, url, id, columns, isDisabled, indexDisplay) {
    if (typeof isDisabled === 'undefined' || isDisabled === null) {
        isDisabled = false;
    }

    if (typeof indexDisplay === 'undefined' || indexDisplay === null || !columns[indexDisplay]) {
        indexDisplay = 1;
    }

    if (!columns[indexDisplay]) {
        indexDisplay = 0;
    }

    url = baseUrl + url;

    $(() => {
        var key = columns[0].name;
        var dataColumns = renderDropdownColumns(columns);

        const makeAsyncDataSource = function () {
            return new DevExpress.data.CustomStore({
                loadMode: 'raw',
                key: key,
                load() {
                    return $.getJSON(url);
                },
                byKey(keyValue) {
                    return $.getJSON(url).then(function (items) {
                        return (items || []).find(function (item) {
                            return String(item[key]) === String(keyValue);
                        }) || null;
                    });
                },
            });
        };

        $('#' + componentId).dxDropDownBox({
            value: id && id !== '00000000-0000-0000-0000-000000000000' && id !== '0' ? id : null,
            valueExpr: key,
            deferRendering: false,
            placeholder: 'Select a value...',
            displayExpr(item) {
                if (!item) return '';
                var displayColumn = columns[indexDisplay] || columns[1] || columns[0];
                return displayColumn ? `${item[displayColumn.name] ?? ''}` : '';
            },
            readOnly: isDisabled,
            showClearButton: true,
            dataSource: makeAsyncDataSource(),
            contentTemplate(e) {
                const value = e.component.option('value');
                const $dataGrid = $('<div>').dxDataGrid({
                    dataSource: e.component.getDataSource(),
                    showColumnLines: true,
                    showRowLines: true,
                    rowAlternationEnabled: true,
                    showBorders: true, filterRow: {
                        visible: true,
                    },
                    headerFilter: {
                        visible: true,
                    },
                    remoteOperations: true,
                    paging: {
                        pageSize: 10,
                    },
                    showBorders: true,
                    columnAutoWidth: true,
                    allowColumnResizing: true,
                    scrolling: {
                        mode: "standard"
                    },
                    loadPanel: {
                        enabled: true
                    },
                    pager: {
                        visible: true,
                        showPageSizeSelector: true,
                        allowedPageSizes: [10, 50, 100],
                        showNavigationButtons: true,
                        showInfo: true
                    },
                    onContentReady: function (x) {
                        var index = DevExpress.localization.formatNumber(x.component.pageIndex() + 1, ",##0.###");
                        var count = DevExpress.localization.formatNumber(x.component.pageCount(), ",##0.###");
                        var total = DevExpress.localization.formatNumber(x.component.totalCount(), ",##0.###");
                        x.component.option("pager.infoText", "Page " + index + " of " + count + " (" + total + " items)");
                    },
                    columns: dataColumns,
                    hoverStateEnabled: true,
                    paging: { enabled: true, pageSize: 10 },
                    filterRow: { visible: true },
                    scrolling: { mode: 'virtual', useNative: false, showScrollbar: 'onScroll' },
                    selection: { mode: 'single' },
                    selectedRowKeys: [value],
                    height: '100%',
                    onSelectionChanged(selectedItems) {
                        const keys = selectedItems.selectedRowKeys;
                        const hasSelection = keys.length;
                        const selectedItem = hasSelection ? selectedItems.selectedRowsData[0] : null;
                        const displayColumn = columns[indexDisplay] || columns[1] || columns[0];
                        const displayText = selectedItem && displayColumn
                            ? `${selectedItem[displayColumn.name] ?? ''}`
                            : '';

                        e.component.option('value', hasSelection ? keys[0] : null);
                        e.component.option('displayValue', displayText);
                        var valueSelect = hasSelection ? keys[0] : null;

                        $('#' + textBoxId).val(valueSelect);
                        if (hasSelection) {
                            e.component.field().val(displayText);
                            e.component.close();
                            window.setTimeout(function () {
                                e.component.field().val(displayText);
                            }, 0);
                        }
                    }
                });

                const dataGrid = $dataGrid.dxDataGrid("instance");
                e.component.on("valueChanged", function (args) {
                    if (args.value === null || args.value === "") {
                        dataGrid.deselectAll();
                        dataGrid.clearSelection();
                    }
                    $('#' + textBoxId).val(args.value);
                });

                return $dataGrid;
            },
        });
    });
}

// Versi SERVER-SIDE dari loadDxDropdownBoxColumn.
// Memuat data per-halaman (paging/filter/sort dikerjakan di server) lewat endpoint
// DevExtreme LoadResult ({ data, totalCount }), bukan mengunduh seluruh tabel.
// - gridUrl   : endpoint LoadResult ber-paging (mis. "/GetData/AssetRegisterDxGrid")
// - byKeyUrl  : endpoint ambil 1 record by Id (mis. "/GetData/AssetRegisterByKey")
// Sisanya identik dengan loadDxDropdownBoxColumn (id, columns, isDisabled, indexDisplay).
function loadDxDropdownBoxColumnRemote(componentId, textBoxId, gridUrl, byKeyUrl, id, columns, isDisabled, indexDisplay) {
    if (typeof isDisabled === 'undefined' || isDisabled === null) {
        isDisabled = false;
    }

    if (typeof indexDisplay === 'undefined' || indexDisplay === null || !columns[indexDisplay]) {
        indexDisplay = 1;
    }

    if (!columns[indexDisplay]) {
        indexDisplay = 0;
    }

    gridUrl = baseUrl + gridUrl;
    byKeyUrl = baseUrl + byKeyUrl;

    var emptyGuid = '00000000-0000-0000-0000-000000000000';

    $(() => {
        var key = columns[0].name;
        var dataColumns = renderDropdownColumns(columns);

        function isNotEmpty(value) {
            return value !== undefined && value !== null && value !== '';
        }

        var initialValue = (id !== null && id !== undefined && id !== '' && id !== emptyGuid && id !== '0') ? id : null;

        const store = new DevExpress.data.CustomStore({
            key: key,
            load(loadOptions) {
                const deferred = $.Deferred();
                const args = {};
                [
                    'skip',
                    'take',
                    'requireTotalCount',
                    'requireGroupCount',
                    'sort',
                    'filter',
                    'totalSummary',
                    'group',
                    'groupSummary',
                ].forEach((i) => {
                    if (i in loadOptions && isNotEmpty(loadOptions[i])) {
                        args[i] = JSON.stringify(loadOptions[i]);
                    }
                });
                $.ajax({
                    url: gridUrl,
                    dataType: 'json',
                    contentType: 'application/json; charset=utf-8',
                    data: args,
                    success(result) {
                        deferred.resolve(result.data, {
                            totalCount: result.totalCount,
                            summary: result.summary,
                            groupCount: result.groupCount,
                        });
                    },
                    error() {
                        deferred.reject('Data loading error');
                    },
                });

                return deferred.promise();
            },
            byKey(keyValue) {
                const deferred = $.Deferred();
                if (keyValue === null || keyValue === undefined || keyValue === '' || keyValue === emptyGuid || keyValue === '0') {
                    return deferred.resolve(null).promise();
                }
                $.ajax({
                    url: byKeyUrl,
                    dataType: 'json',
                    data: { id: keyValue },
                    success(result) {
                        deferred.resolve(result);
                    },
                    error() {
                        deferred.resolve(null);
                    },
                });

                return deferred.promise();
            },
        });

        $('#' + componentId).dxDropDownBox({
            value: initialValue,
            valueExpr: key,
            deferRendering: false,
            placeholder: 'Select a value...',
            displayExpr(item) {
                if (!item) return '';
                var displayColumn = columns[indexDisplay] || columns[1] || columns[0];
                return displayColumn ? `${item[displayColumn.name] ?? ''}` : '';
            },
            readOnly: isDisabled,
            showClearButton: true,
            dataSource: store,
            contentTemplate(e) {
                const value = e.component.option('value');
                const $dataGridEl = $('<div>').dxDataGrid({
                    dataSource: store,
                    showColumnLines: true,
                    showRowLines: true,
                    rowAlternationEnabled: true,
                    showBorders: true,
                    filterRow: {
                        visible: true,
                    },
                    headerFilter: {
                        visible: true,
                    },
                    remoteOperations: true,
                    paging: {
                        pageSize: 10,
                    },
                    columnAutoWidth: true,
                    allowColumnResizing: true,
                    scrolling: {
                        mode: 'standard',
                        useNative: false,
                        showScrollbar: 'onScroll'
                    },
                    loadPanel: {
                        enabled: true
                    },
                    pager: {
                        visible: true,
                        showPageSizeSelector: true,
                        allowedPageSizes: [10, 50, 100],
                        showNavigationButtons: true,
                        showInfo: true
                    },
                    onContentReady: function (x) {
                        var index = DevExpress.localization.formatNumber(x.component.pageIndex() + 1, ",##0.###");
                        var count = DevExpress.localization.formatNumber(x.component.pageCount(), ",##0.###");
                        var total = DevExpress.localization.formatNumber(x.component.totalCount(), ",##0.###");
                        x.component.option("pager.infoText", "Page " + index + " of " + count + " (" + total + " items)");
                    },
                    columns: dataColumns,
                    hoverStateEnabled: true,
                    selection: { mode: 'single' },
                    selectedRowKeys: value ? [value] : [],
                    height: '100%',
                    onSelectionChanged(selectedItems) {
                        const keys = selectedItems.selectedRowKeys;
                        const hasSelection = keys.length;

                        e.component.option('value', hasSelection ? keys[0] : null);
                        var valueSelect = hasSelection ? keys[0] : null;

                        if (valueSelect === null && id !== null && id !== "") {
                            if (id !== emptyGuid && id !== '0') {
                                valueSelect = id;
                                e.component.option('value', id);
                            }
                        }

                        $('#' + textBoxId).val(valueSelect);
                        if (hasSelection) {
                            e.component.close();
                        }
                    }
                });

                const dataGrid = $dataGridEl.dxDataGrid('instance');
                e.component.on("valueChanged", function (args) {
                    if (args.value === null || args.value === "") {
                        dataGrid.deselectAll();
                        dataGrid.clearSelection();
                    }
                    $('#' + textBoxId).val(args.value);
                });

                return $dataGridEl;
            },
        });
    });
}

