function loadDxDropdownBoxColumnMultiple(componentId, textBoxId, url, id, columns, isDisabled, displayIndex) {
    if (typeof isDisabled === 'undefined' || isDisabled === null) {
        isDisabled = false;
    }

    if (typeof displayIndex === 'undefined' || displayIndex === null || !columns[displayIndex]) {
        displayIndex = 1;
    }

    if (!columns[displayIndex]) {
        displayIndex = 0;
    }

    url = baseUrl + url;

    $(() => {
        var key = columns[0].name;
        var value = columns[displayIndex].name;
        var dataColumns = renderDropdownColumns(columns);
        var initialValues = [];

        if (Array.isArray(id)) {
            initialValues = id.filter(item => item !== null && item !== undefined && item !== '');
        }
        else if (id !== null && id !== undefined && id !== '' &&
            id !== '00000000-0000-0000-0000-000000000000' && id !== '0') {
            initialValues = id.toString().split(',').map(item => item.trim()).filter(Boolean);
        }

        const makeAsyncDataSource = function () {
            return new DevExpress.data.CustomStore({
                loadMode: 'raw',
                key: key,
                load() {
                    return $.getJSON(url);
                },
            });
        };

        $('#' + componentId).dxDropDownBox({
            value: initialValues,
            valueExpr: key,
            deferRendering: false,
            placeholder: 'Select a value...',
            displayExpr: value,
            readOnly: isDisabled,
            showClearButton: true,
            dataSource: makeAsyncDataSource(),
            contentTemplate(e) {
                const value = e.component.option('value');
                const $dataGrid = $('<div>').dxDataGrid({
                    dataSource: e.component.getDataSource(),
                    showColumnLines: true,
                    showRowLines: true,
                    rowAlternationEnabled: true,
                    showBorders: true, filterRow: {
                        visible: true,
                    },
                    headerFilter: {
                        visible: true,
                    },
                    remoteOperations: true,
                    paging: {
                        pageSize: 10,
                    },
                    showBorders: true,
                    columnAutoWidth: true,
                    allowColumnResizing: true,
                    scrolling: {
                        mode: "standard"
                    },
                    loadPanel: {
                        enabled: true
                    },
                    pager: {
                        visible: true,
                        showPageSizeSelector: true,
                        allowedPageSizes: [10, 50, 100],
                        showNavigationButtons: true,
                        showInfo: true
                    },
                    onContentReady: function (x) {
                        var index = DevExpress.localization.formatNumber(x.component.pageIndex() + 1, ",##0.###");
                        var count = DevExpress.localization.formatNumber(x.component.pageCount(), ",##0.###");
                        var total = DevExpress.localization.formatNumber(x.component.totalCount(), ",##0.###");
                        x.component.option("pager.infoText", "Page " + index + " of " + count + " (" + total + " items)");
                    },
                    columns: dataColumns,
                    hoverStateEnabled: true,
                    paging: { enabled: true, pageSize: 10 },
                    filterRow: { visible: true },
                    scrolling: { mode: 'virtual', useNative: false, showScrollbar: 'onScroll' },
                    selection: { mode: 'multiple' },
                    height: '100%',
                    onSelectionChanged(selectedItems) {
                        var keys = selectedItems.selectedRowKeys;

                        e.component.option('value', keys);
                        $('#' + textBoxId).val(keys.join(',')).trigger('change');
                    },
                    selectNodesRecursive: false,
                    showCheckBoxesMode: 'normal',
                    selectedRowKeys: value || [],
                });

                var dataGrid = $dataGrid.dxDataGrid('instance');

                e.component.on('valueChanged', (args) => {
                    var values = Array.isArray(args.value)
                        ? args.value
                        : (args.value === null || args.value === undefined || args.value === ''
                            ? []
                            : args.value.toString().split(',').map(item => item.trim()).filter(Boolean));

                    $('#' + textBoxId).val(values.join(',')).trigger('change');
                    syncDataGridSelection(dataGrid, values);
                });

                const syncDataGridSelection = function (dataGridInstance, value) {
                    if (!value.length) {
                        dataGridInstance.deselectAll();
                        dataGridInstance.clearSelection();
                    }
                    else {
                        dataGridInstance.selectRows(value, false);
                    }
                };
                return $dataGrid;
            },
        });
    });
}

